def _transform(pattern: _BranchPattern) -> _Either:
    """Expand pattern into an (almost) equivalent one, but with single _Either.

    Example: ((-a | -b) (-c | -d)) => (-a -c | -a -d | -b -c | -b -d)
    Quirks: [-a] => (-a), (-a...) => (-a -a)
    """
    result = []
    groups = [[pattern]]
    while groups:
        children = groups.pop(0)
        parents = [c for c in children if isinstance(c, _BranchPattern)]
        if any(isinstance(c, _Either) for c in parents):
            child = [c for c in children if isinstance(c, _Either)][0]
            children.remove(child)
            for grandchild in child.children:
                groups.append([c for c in children if c is not child] + [grandchild])
        elif any(isinstance(c, _OneOrMore) for c in parents):
            # ...)
            child = [c for c in children if isinstance(c, _OneOrMore)][0]
            children.remove(child)
            groups.append(children + [child.children[0]] * 2)
        elif any(isinstance(c, _NotRequired) for c in parents):
            child = [c for c in children if isinstance(c, _NotRequired)][0]
            children.remove(child)
            groups.append(children + [c for c in child.children])
            groups.append(children)
        elif any(isinstance(c, _OptionsShortcut) for c in parents):
            child = [c for c in children if isinstance(c, _OptionsShortcut)][0]
            children.remove(child)
            groups.append(children + [c for c in child.children])
            groups.append(children)
        else:
            result.append(children)
    return _Either(*[_Required(*e) for e in result])
