def c1():
    r = docopt('Usage: prog.py [-h] [--version] <input> [--output=<file>]\nOptions:\n  -h --help  Show help.\n  --version  Show version.\n  --output=<file>  Output file.', argv=['input.txt', '--output=out.txt'])
    assert r == {'<input>': 'input.txt', '--output': 'out.txt', '--help': False, '--version': False, '-h': False}, r


def c2():
    r = docopt('Usage: prog.py [--repeat=<n>] <file>...\nOptions:\n  --repeat=<n>  Repeat count [default: 1].', argv=['f1', 'f2', '--repeat=3'])
    assert r == {'<file>': ['f1', 'f2'], '--repeat': '3'}, r


def c3():
    r = docopt('Usage:\n  git add <file>...\n  git commit -m <msg>\n  git push [origin] [master]', argv=['commit', '-m', 'init'])
    assert r == {'add': False, 'commit': True, 'push': False, '<file>': None, '-m': True, '<msg>': 'init', 'origin': False, 'master': False}, r


def c4():
